#!/usr/bin/env python3
"""external-data-in-inferred-places.py <seed>: a primitive from external data travels through places whose types are only inferred: variables, functions, properties, fields, parameters, generic calls.
The seed picks the way and the kind of data: an even seed a string where a number is declared, an odd seed a number where a string is declared. Each program uses the value in every way. The program type-checks.
As plain Bun, line by line."""
import sys
seed = int(sys.argv[1]); f = "ns"[seed % 2]; GOOD = {"n": "1", "s": "'z'"}[f]; T = {"n": "number", "s": "string"}[f]; X = "data." + f
CARRY = [("direct", "const taken = X;"), ("a const", "const a = X; const taken = a;"), ("a let", "let a = GOOD; a = X; const taken = a;"), ("a var", "var a = GOOD; a = X; const taken = a;"), ("two lets", "let a = GOOD, b = GOOD; a = X; b = a; const taken = b;"), ("a let assigned in a branch", "let a = GOOD; if (hide(true)) a = X; const taken = a;"), ("a let assigned in a loop", "let a = GOOD; for (let i = 0; i < 2; i++) a = X; const taken = a;"), ("a let assigned in a closure", "let a = GOOD; const set = () => { a = X; }; set(); const taken = a;"), ("a let assigned in try", "let a = GOOD; try { a = X; } finally { } const taken = a;"), ("a let assigned in a switch", "let a = GOOD; switch (hide(1)) { case 1: a = X; break; default: a = GOOD; } const taken = a;"),
 ("ternary", "const taken = hide(true) ? X : GOOD;"), ("ternary, other arm", "const taken = hide(false) ? GOOD : X;"), ("||", "const taken = X || GOOD;"), ("&&", "const taken = hide(true) && X;"), ("??", "const taken = X ?? GOOD;"), ("comma", "const taken = (hide(0), X);"), ("assignment as a value", "let a = GOOD; const taken = (a = X);"), 
 ("an arrow", "const g = () => X; const taken = g();"), ("a declaration", "function g() { return X; } const taken = g();"), ("a function expression", "const g = function () { return X; }; const taken = g();"), ("called at once", "const taken = (() => X)();"), ("two functions deep", "const g = () => X; const h = () => g(); const taken = h();"), ("returned in a branch", "const g = (b: boolean) => { if (b) return X; return GOOD; }; const taken = g(true);"), ("returned through a let", "const g = () => { let a = GOOD; a = X; return a; }; const taken = g();"), ("a method of a literal", "const o = { m() { return X; } }; const taken = o.m();"), ("an arrow in a literal", "const o = { m: () => X }; const taken = o.m();"), ("a method of a class", "class K { m() { return X; } } const taken = new K().m();"), ("a static method", "class K { static m() { return X; } } const taken = K.m();"), ("a private method", "class K { #m() { return X; } go() { return this.#m(); } } const taken = new K().go();"), ("a getter of a literal", "const o = { get g() { return X; } }; const taken = o.g;"), ("a getter of a class", "class K { get g() { return X; } } const taken = new K().g;"),
 ("identity", "const same = <V,>(v: V): V => v; const taken = same(X);"), ("an inferred parameter by default", "const g = (p = GOOD) => p; const taken = g(X);"), ("a callback's parameter", "const run = <V,>(v: V, k: (v: V) => V): V => k(v); const taken = run(X, v => v);"), ("a rest parameter by inference", "const first = <V,>(...all: V[]): V => all[0]; const taken = first(X);"), ("bind", "const g = (p = GOOD) => p; const taken = g.bind(null, X)();"), ("call", "const g = function (p = GOOD) { return p; }; const taken = g.call(null, X);"), ("apply", "const g = function (p = GOOD) { return p; }; const taken = g.apply(null, [X]);"),
 ("a literal property", "const o = { v: X }; const taken = o.v;"), ("a literal property, assigned", "const o = { v: GOOD }; o.v = X; const taken = o.v;"), ("shorthand", "const v = X; const o = { v }; const taken = o.v;"), ("a computed key", "const k = 'v' as const; const o = { [k]: X }; const taken = o.v;"), ("a nested literal", "const o = { in: { v: X } }; const taken = o.in.v;"), ("a spread of a literal", "const o = { v: X }; const p = { ...o }; const taken = p.v;"), ("a spread overridden", "const o = { v: GOOD }; const p = { ...o, v: X }; const taken = p.v;"), ("Object.assign", "const o = Object.assign({ v: GOOD }, { v: X }); const taken = o.v;"), ("destructured", "const { v: taken } = { v: X };"), ("destructured with a default", "const { v: taken = GOOD } = { v: X } as { v?: TYPE };"), ("optional chain", "const o: { v: TYPE } | undefined = hide({ v: X }); const taken = o?.v ?? GOOD;"), ("by a key variable", "const o = { v: X }; const k: keyof typeof o = 'v'; const taken = o[k];"), ("Object.values", "const taken = Object.values({ v: X })[0];"), ("Object.entries", "const taken = Object.entries({ v: X })[0][1];"),
 ("a class field", "class K { v = X; } const taken = new K().v;"), ("a class field, assigned", "class K { v = GOOD; } const k = new K(); k.v = X; const taken = k.v;"), ("a field set in the constructor", "class K { v = GOOD; constructor() { this.v = X; } } const taken = new K().v;"), ("a constructor parameter", "class K { v; constructor(p = GOOD) { this.v = p; } } const taken = new K(X).v;"), ("a parameter property", "class K { constructor(public v = GOOD) {} } const taken = new K(X).v;"), ("a private field", "class K { #v = X; get() { return this.#v; } } const taken = new K().get();"), ("a static field", "class K { static v = X; } const taken = K.v;"), ("an inherited field", "class B { v = X; } class K extends B {} const taken = new K().v;"), ("a setter and a getter", "class K { #v = GOOD; set v(p) { this.#v = p; } get v() { return this.#v; } } const k = new K(); k.v = X; const taken = k.v;"),
 ("a tuple", "const t = [X, GOOD] as const; const taken = t[0];"), ("a pair returned", "const g = () => [X, GOOD] as const; const [taken] = g();"), ("a module variable", "shared = X; const taken = shared;"), ("a module variable read in a function", "shared = X; const g = () => shared; const taken = g();"), ("a template type", "const taken = [X].map(v => v)[0];"), ("a label and break", "let a = GOOD; out: { a = X; break out; } const taken = a;"), ("a generator", "function* g() { yield X; } const taken = [...g()][0];"), ("a WeakMap", "const k = {}; const w = new WeakMap([[k, GOOD]]); w.set(k, X); const taken = w.get(k)!;"), ("a Map of literals", "const m = new Map([[1, { v: GOOD }]]); m.set(2, { v: X }); const taken = m.get(2)!.v;"), ("an array of literals", "const l = [{ v: GOOD }]; l.push({ v: X }); const taken = l[1].v;"), ("JSON round trip of a literal", "const o = { v: GOOD }; const p: typeof o = JSON.parse(JSON.stringify({ v: X })); const taken = p.v;"), ("structuredClone of a literal", "const taken = structuredClone({ v: X }).v;")]
USE = [("+ 1", "V + 1"), ("1 +", "1 + V"), ("typeof", "typeof V"), ("template", "`<${V}>`"), ("=== itself", "V === X"), ("truthiness", "V ? 'yes' : 'no'"), ("+= on a let", "(() => { let n = GOOD; n += V; return n; })()"), ("String", "String(V)"), ("stored and read", "(() => { let n = GOOD; n = V; return n + 1; })()"), ("in a literal and out", "({ w: V }).w + 1"), ("in an array and out", "[V][0] + 1"), ("returned", "(() => V)() + 1"), ("switch", "(() => { switch (V) { case GOOD: return 'good'; default: return 'other'; } })()"), ("as a key", "({ [V]: 1 })[V]"), ("JSON", "JSON.stringify({ v: V })")]
if f == "n": USE += [("* 2", "V * 2"), ("negated", "-V"), ("compared", "V < 5"), ("incremented", "(() => { let n = GOOD; n = V; n++; return n; })()"), ("Math.max", "Math.max(V, 0)"), ("| 0", "V | 0"), ("toFixed guarded", "typeof V === 'number' ? V.toFixed(1) : 'no number'"), ("as an index", "[10, 20][V]"), ("isNaN", "Number.isNaN(V)")]
else: USE += [(".length", "V.length"), ("compared", "V < 'm'"), ("twice", "V + V"), ("guarded method", "typeof V === 'string' ? V.toUpperCase() : 'no string'"), ("concatenated", "'<' + V + '>'")]
out = ["declare const console: { log(text: string): void }; declare function structuredClone<T>(value: T): T;", "const data = JSON.parse('{\"n\":\"abc\",\"s\":5}') as { n: number; s: string };", "const boxes: unknown[] = []; const hide = <T,>(x: T): T => { boxes.push(x); return boxes.pop() as T; };", "let shared = GOOD;".replace("GOOD", GOOD),
       "const show = (v: unknown): string => v === undefined ? '<undefined>' : v === null ? '<null>' : typeof v === 'number' ? (Object.is(v, -0) ? '<-0>' : String(v)) : typeof v === 'string' ? JSON.stringify(v) : String(v);",
       "const say = (label: string, f: () => unknown): void => { let r: string; try { r = show(f()); } catch (e) { r = 'throws ' + (e as Error).constructor.name + (String((e as Error).message).includes('(bun compile') ? ' by the compiler' : ''); } console.log(label + ' ==> ' + r); };"]
k = 0
ct, c = CARRY[seed // 2]
if True:
    for ut, u in USE:
        k += 1
        out.append("function f%d() { %s return %s; } say(%r, f%d);" % (k, c.replace("GOOD", GOOD).replace("TYPE", T).replace("X", X), u.replace("V", "taken").replace("GOOD", GOOD).replace("X", X), "%s | %s" % (ct, ut), k))
print("\n".join(out))
